"""Keep299 general assertions and eight prior focused checks; add seven Palantir/role/warning checks."""
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent))
from setup_deseq2_reference import ROOT

EXTRA=r'''
 await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:8768/literature-review.html');await page.evaluate(()=>document.documentElement.dataset.theme='light');await page.locator('#tools-tab').click();await page.locator('#query').fill('Palantir');const pal=page.locator('#results article').filter({has:page.getByRole('heading',{name:/^Palantir \(/i})});assert.equal(await pal.count(),1);const pt=(await pal.innerText()).toLowerCase();for(const term of ['PalantirWorkflowCli','1.4.4','1.4.6','Twenty-one','multiscale','upstream','preclip','entropy','DataFrame','scFates'])assert(pt.includes(term.toLowerCase()),term);await pal.screenshot({path:path.join(out,'palantir-card-desktop.png'),style:'header{visibility:hidden!important}'});checks.push('Palantir card exposes both original editions,21 workflows and native-versus-upstream scientific boundaries');
 const currentPal=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/omics-2023-2026/tool-inventory.json'))).find(t=>t.id==='palantir');const palProof=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/palantir-workflow-development/VALIDATION.json')));assert.equal(currentPal.implementation_status,'upstream-adapter-validated');assert.equal(currentPal.development_candidate,palProof.artifact.path);assert.equal(currentPal.development_candidate_sha256,palProof.artifact.sha256);assert.equal(currentPal.development_cli_class,'org.jlinalg.cli.PalantirWorkflowCli');assert.equal(currentPal.runtime_setup_cli_class,'org.jlinalg.cli.PalantirSetupCli');assert.equal(currentPal.independent_trajectory_refit,false);assert.equal(currentPal.analysis_installs_software,false);assert.equal(currentPal.canonical_adapter_available,false);checks.push('Palantir points to the exact standalone artifact and setup class without release or independent-refit credit');
 for(const name of ['scFates','SAW','Stereopy','DoRothEA']){await page.locator('#query').fill(name);const selected=page.locator('#results article').filter({has:page.getByRole('heading',{name:new RegExp('^'+name+' \\(','i')})});assert.equal(await selected.count(),1);assert((await selected.innerText()).toLowerCase().includes('missing'));}checks.push('the four newly registered tree/spatial/resource tools remain missing');
 const trajectory=JSON.parse(fs.readFileSync(path.join(root,'tools/literature/trajectory-spatial-use-reviews.json'))).reviews;await page.locator('#papers-tab').click();for(const id of [...new Set(trajectory.map(d=>d.paper_id))]){const paper=papers.find(p=>p.paper_id===id);await page.locator('#query').fill(paper.doi);assert.equal(await page.locator('#results article').count(),1);const all=clean(await page.locator('#'+id).textContent());for(const d of trajectory.filter(d=>d.paper_id===id)){assert(all.includes(clean(d.review.use_summary)),id+'/'+d.review.tool_id);assert(all.includes(clean(d.review.implementation_scope_note)),id+'/'+d.review.tool_id+' scope');}}checks.push('all eight applied roles display across four papers with root-selection, scFates and version/conversion/resource distinctions');
 await page.goto('http://127.0.0.1:8768/literature-warnings.html');const palActions=page.locator('#palantir-required-actions');assert(await palActions.isVisible());const pa=(await palActions.innerText()).toLowerCase();for(const term of ['SKIP3','FAIL2','earlier successes','permission flags','case-sensitive','NEW paths','RUN installs nothing','empty_fates=fail','retain-pseudotime-only','renormalization','entropy','DataFrame','AnnData','original-error.traceback','OS CPU/memory'])assert(pa.includes(term.toLowerCase()),term);await palActions.screenshot({path:path.join(out,'palantir-actions-desktop.png'),style:'header{visibility:hidden!important}'});checks.push('prominent Palantir setup/skip/failure recovery and original clipping/empty-fate warnings are actionable');
 await page.setViewportSize({width:390,height:1000});await page.evaluate(()=>document.documentElement.dataset.theme='dark');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await palActions.screenshot({path:path.join(out,'palantir-actions-mobile-dark.png'),style:'header{visibility:hidden!important}'});assert.equal(errors.length,0,errors.join('\n'));checks.push('Palantir dark warnings fit390px without overflow or browser errors');
 const newRoles=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/omics-2023-2026/palantir-role-coverage.json')));assert.equal(newRoles.prior_reviews_preserved,980);assert.equal(newRoles.new_reviews,8);assert.equal(newRoles.total_reviews,988);assert.equal(newRoles.total_observations,2465);assert.equal(newRoles.supporting_pointers,340);assert.equal(newRoles.distinct_named_tools,400);assert.equal(newRoles.changed_paper_roles.length,4);checks.push('current400 tools,2465 observations,988 reviewed uses and340 supporting pointers match the exact additive ledger');
'''

def generated():
 tools=ROOT/'tools/literature';text=(tools/'check_cellphonedb_effective_review_ui.cjs').read_text();old="assert.equal(inventory.length,395);";assert text.count(old)==1;text=text.replace(old,"assert.equal(inventory.length,400);").replace("['upstream-adapter-validated',68],['missing',251]","['upstream-adapter-validated',69],['missing',255]").replace('395 cataloged tools,85 new integrations,251 missing,2457 observations and980 reviewed uses agree','400 cataloged tools,86 new integrations,255 missing; the historical CellPhoneDB ledger remains unchanged');marker=' const inventory=JSON.parse';assert text.count(marker)==1;text=text.replace(marker,EXTRA+marker);text=text.replace('cellphonedb-ui-verification.json','palantir-ui-verification.json').replace('Passed6 focused CellPhoneDB browser checks','Passed15 focused current CellPhoneDB and Palantir browser checks');wrapper=(tools/'validate_cellphonedb_effective_ui.py').read_text().replace('check_cellphonedb_effective_review_ui.cjs','check_palantir_review_ui.cjs').replace('build/literature-review/cellphonedb-runtime','build/literature-review/palantir-runtime').replace("('cellphonedb',","('palantir',").replace("out/'cellphonedb/cellphonedb-ui-verification.json'","out/'palantir/palantir-ui-verification.json'").replace('cellphonedb=pin(','palantir=pin(').replace('passed-local-general-and-cellphonedb-catalog-browser-checks','passed-local-general-and-palantir-catalog-browser-checks');wrapper=wrapper.replace('from setup_deseq2_reference import ROOT, pin, save','sys.path.insert(0,str(Path(__file__).resolve().parent))\nfrom setup_deseq2_reference import ROOT, pin, save');return {tools/'check_palantir_review_ui.cjs':text.encode(),tools/'validate_palantir_catalog_ui.py':wrapper.encode()}

def verify():
 for path,raw in generated().items():assert path.read_bytes()==raw,'Current focused UI derivation differs: '+str(path)
if __name__=='__main__':
 for path,raw in generated().items():
  if path.exists():assert path.read_bytes()==raw,'Existing generated UI checks protected'
  else:path.write_bytes(raw)
 verify();print('Prepared299 unchanged general assertions and15 additive current-tool browser checks')
